{
  "meta": {
    "name": "SalonBooker",
    "description": "A booking app for a hair salon where customers can book appointments with stylists for services, staff can manage the schedule, and a premium feature unlocks SMS reminders."
  },
  "entities": [
    {
      "name": "Customer",
      "ownable": true,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "contactInfo",
          "type": "string",
          "required": true
        }
      ]
    },
    {
      "name": "Stylist",
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "specialty",
          "type": "string"
        }
      ]
    },
    {
      "name": "Service",
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "duration",
          "type": "integer",
          "required": true
        },
        {
          "name": "price",
          "type": "number",
          "required": true
        }
      ]
    },
    {
      "name": "Appointment",
      "ownable": true,
      "fields": [
        {
          "name": "dateTime",
          "type": "datetime",
          "required": true
        },
        {
          "name": "status",
          "type": "enum",
          "required": true,
          "enumValues": [
            "booked",
            "confirmed",
            "cancelled",
            "completed"
          ],
          "default": "booked"
        }
      ],
      "relations": [
        {
          "name": "customer",
          "kind": "manyToOne",
          "target": "Customer",
          "required": true
        },
        {
          "name": "stylist",
          "kind": "manyToOne",
          "target": "Stylist",
          "required": true
        },
        {
          "name": "service",
          "kind": "manyToOne",
          "target": "Service",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "customer",
      "isDefault": true
    },
    {
      "name": "stylist"
    },
    {
      "name": "admin"
    }
  ],
  "permissions": [
    {
      "role": "customer",
      "entity": "Appointment",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "stylist",
      "entity": "Appointment",
      "actions": [
        "read",
        "update"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Customer",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Stylist",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Service",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Appointment",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Appointments",
      "route": "/appointments",
      "type": "list",
      "entity": "Appointment",
      "access": [
        "customer",
        "stylist",
        "admin"
      ]
    },
    {
      "name": "Book Appointment",
      "route": "/appointments/new",
      "type": "form",
      "entity": "Appointment",
      "access": [
        "customer"
      ]
    },
    {
      "name": "Manage Appointments",
      "route": "/manage-appointments",
      "type": "list",
      "entity": "Appointment",
      "access": [
        "stylist",
        "admin"
      ]
    },
    {
      "name": "Services",
      "route": "/services",
      "type": "list",
      "entity": "Service",
      "access": [
        "admin"
      ]
    },
    {
      "name": "Stylists",
      "route": "/stylists",
      "type": "list",
      "entity": "Stylist",
      "access": [
        "admin"
      ]
    },
    {
      "name": "Customers",
      "route": "/customers",
      "type": "list",
      "entity": "Customer",
      "access": [
        "admin"
      ]
    },
    {
      "name": "SMS Reminders Settings",
      "route": "/settings/sms",
      "type": "custom",
      "access": [
        "admin"
      ],
      "requiresPlan": "premium"
    }
  ],
  "plans": [
    {
      "name": "free",
      "isDefault": true,
      "features": []
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": [
        "smsReminders"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "smsRemindersGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "SMS Reminders Settings"
        ],
        "features": [
          "smsReminders"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "customerAppointmentOwnership",
      "entity": "Appointment"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
